#!/usr/bin/env node
// Expand the beta curriculum in content/drafts/lesson_01.json into the full
// seven-level, 59-lesson plan described in
// thoughts/arabic-grammar/plans/curriculum-plan.md, plus an introductory
// Alfiyyat Ibn Malik track (Level 7).
//
// This script:
//   - Preserves lesson_01 through lesson_09 exactly, except that it backfills
//     a fourth primary/repeat exercise for lesson_01 and a repeat-exercise
//     bank for lessons 2-6 (lessons 7-9 already have repeat banks and are
//     left untouched).
//   - Appends original, bilingual, pendingReview lessons 10-51 covering
//     Levels 2 (cont'd) through 6 exactly as laid out in the curriculum plan.
//   - Appends original, bilingual, pendingReview lessons 52-59 covering a new
//     Level 7: an introductory sequence of core Alfiyyat Ibn Malik topics,
//     ending in an unvocalized reading checkpoint (lesson_59). A small,
//     carefully chosen set of individual verses from this public-domain
//     13th-century poem are quoted verbatim and explicitly cited; every
//     explanation, translation, feedback string, and exercise is original
//     to this application, never copied from any modern commentary.
//   - Rebuilds the top-level "levels" array to describe all seven levels.
//   - Writes the result back to content/drafts/lesson_01.json, pretty
//     printed with a trailing newline.
//
// The file is organized around small helper builders (bi, example, section,
// option, exercise, ex3, lesson) instead of embedding raw JSON, so lesson
// content stays readable and every builder fails loudly (throws) the moment
// a token target is missing or a count requirement (objectives, exercises,
// options, correct-answer count, etc.) is violated.

import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(__dirname, '..');
const CATALOG_PATH = join(REPO_ROOT, 'content', 'drafts', 'lesson_01.json');

const CONTENT_VERSION = '7.0.0-draft.1';

// ---------------------------------------------------------------------------
// Primitive helper builders
// ---------------------------------------------------------------------------

/** Bilingual text pair, matching the schema's `localizedText` shape. */
const bi = (en, ar) => {
  if (!en || !ar) {
    throw new Error(`bi() requires non-empty en/ar strings, got en=${JSON.stringify(en)} ar=${JSON.stringify(ar)}`);
  }
  return { en, ar };
};

/**
 * Locate `target` inside `unvocalized` starting at `cursor`. Throws loudly if
 * the target is missing so a typo in lesson content is caught immediately
 * instead of silently producing a bad token span.
 */
function findToken(unvocalized, target, cursor, exampleId) {
  const idx = unvocalized.indexOf(target, cursor);
  if (idx === -1) {
    throw new Error(
      `[example ${exampleId}] target "${target}" not found in "${unvocalized}" starting at index ${cursor}. ` +
        'Check spelling/order of tokenSpecs.',
    );
  }
  return { idx, end: idx + target.length };
}

/**
 * Build a grammar example. `tokenSpecs` are matched against `unvocalized`
 * left-to-right using a moving cursor, so every token's start/end is derived
 * directly from the text instead of being hand-counted (which is the usual
 * source of span mistakes). Overlap and mis-ordering are impossible by
 * construction, and a missing target throws immediately.
 */
function example(id, vocalized, unvocalized, tokenSpecs) {
  let cursor = 0;
  const tokens = tokenSpecs.map((spec) => {
    const { idx, end } = findToken(unvocalized, spec.target, cursor, id);
    cursor = end;
    return {
      text: spec.target,
      start: idx,
      end,
      role: bi(spec.roleEn, spec.roleAr),
      grammarState: spec.state,
      grammaticalSign: bi(spec.signEn, spec.signAr),
      ending: spec.ending,
      reason: bi(spec.reasonEn, spec.reasonAr),
    };
  });
  for (const tok of tokens) {
    const actual = unvocalized.substring(tok.start, tok.end);
    if (actual !== tok.text) {
      throw new Error(`[example ${id}] span mismatch: expected "${tok.text}" but slice was "${actual}"`);
    }
  }
  return { id, vocalized, unvocalized, tokens };
}

/** A lesson section (introduction / workedExample / ruleSummary / checkpoint). */
function section(id, type, titleEn, titleAr, bodyEn, bodyAr, examples = []) {
  const validTypes = ['introduction', 'workedExample', 'ruleSummary', 'checkpoint'];
  if (!validTypes.includes(type)) {
    throw new Error(`section ${id}: unsupported type ${type}`);
  }
  return { id, type, title: bi(titleEn, titleAr), body: bi(bodyEn, bodyAr), examples };
}

/** A single exercise option. */
function option(id, labelEn, labelAr, isCorrect, feedbackEn, feedbackAr) {
  return { id, label: bi(labelEn, labelAr), isCorrect: !!isCorrect, feedback: bi(feedbackEn, feedbackAr) };
}

const EXERCISE_TYPES = ['chooseEnding', 'identifyRole', 'identifyState', 'matchRule', 'addTashkeel'];

/** An exercise built from already-constructed options. Enforces schema rules. */
function exercise(id, type, promptEn, promptAr, options) {
  if (!EXERCISE_TYPES.includes(type)) {
    throw new Error(`exercise ${id}: unsupported type ${type}`);
  }
  if (options.length !== 3) {
    throw new Error(`exercise ${id}: must have exactly 3 options, got ${options.length}`);
  }
  const correctCount = options.filter((o) => o.isCorrect).length;
  if (correctCount !== 1) {
    throw new Error(`exercise ${id}: must have exactly one correct option, got ${correctCount}`);
  }
  const seenIds = new Set();
  for (const o of options) {
    if (seenIds.has(o.id)) {
      throw new Error(`exercise ${id}: duplicate option id "${o.id}"`);
    }
    seenIds.add(o.id);
  }
  return { id, type, prompt: bi(promptEn, promptAr), options };
}

/**
 * Compact three-option exercise builder. `correct`/`wrong1`/`wrong2` are
 * plain objects: { id, en, ar, fbEn, fbAr }. This is the main way lesson
 * specs below build exercises without repeating option() boilerplate.
 */
function ex3(id, type, promptEn, promptAr, correct, wrong1, wrong2) {
  return exercise(id, type, promptEn, promptAr, [
    option(correct.id, correct.en, correct.ar, true, correct.fbEn, correct.fbAr),
    option(wrong1.id, wrong1.en, wrong1.ar, false, wrong1.fbEn, wrong1.fbAr),
    option(wrong2.id, wrong2.en, wrong2.ar, false, wrong2.fbEn, wrong2.fbAr),
  ]);
}

