const SOURCE_LOCALIZATIONS = {
  'ajurrumiyya-original': AJURRUMIYYA_SOURCE,
  'madinah-book-1-concepts': {
    id: 'madinah-book-1-concepts',
    title: bi('Madinah Arabic Book 1', 'دروس اللغة العربية لغير الناطقين بها - الكتاب الأول'),
    author: bi('V. Abdur Rahim', 'الدكتور ف. عبد الرحيم'),
    url: null,
    licenseStatus: 'conceptualReference',
    citation: bi(
      'Only the general beginner progression was consulted. No prose, translation, exercise, or lesson arrangement was copied.',
      'رُوجع التسلسل العام للمبتدئين فقط، ولم يُنسخ أي نص أو ترجمة أو تمرين أو ترتيب للدروس.',
    ),
  },
  'arabic-grammar-original-content': ORIGINAL_SOURCE,
  'alfiyyat-ibn-malik-original': ALFIYYA_SOURCE,
};

function localizeSource(source) {
  const localized = SOURCE_LOCALIZATIONS[source.id];
  if (!localized) {
    throw new Error(`missing bilingual source metadata for ${source.id}`);
  }
  return { ...source, ...localized, url: source.url ?? localized.url };
}

function pendingReview(notes) {
  return { status: 'pendingReview', contentVersion: CONTENT_VERSION, reviewer: null, reviewedAt: null, notes };
}

/**
 * Build a full lesson object from a compact spec. Every new lesson (10-51)
 * is created through this function, which enforces:
 *   - 1-2 objectives
 *   - exactly 4 primary exercises and 4 repeat exercises
 *   - at least one introduction section and one workedExample section
 *   - at least one worked example with tokens
 *   - at least one "original" licensed source
 */
function lesson(spec) {
  const {
    id,
    order,
    titleEn,
    titleAr,
    objectives,
    prerequisites,
    estimatedMinutes,
    sections,
    exercises,
    repeatExercises,
    sources,
    notes,
  } = spec;

  if (!/^lesson_[0-9]{2}$/.test(id)) {
    throw new Error(`lesson id "${id}" must match lesson_XX`);
  }
  if (objectives.length < 1 || objectives.length > 2) {
    throw new Error(`${id}: objectives must contain 1-2 items, got ${objectives.length}`);
  }
  if (!Array.isArray(sections) || sections.length < 2) {
    throw new Error(`${id}: expected at least two sections (introduction + workedExample)`);
  }
  if (!sections.some((s) => s.type === 'introduction')) {
    throw new Error(`${id}: missing an introduction section`);
  }
  if (!sections.some((s) => s.type === 'workedExample')) {
    throw new Error(`${id}: missing a workedExample section`);
  }
  if (!sections.some((s) => s.examples && s.examples.length > 0 && s.examples.some((e) => e.tokens.length > 0))) {
    throw new Error(`${id}: expected at least one worked example with tokens`);
  }
  if (exercises.length !== 4) {
    throw new Error(`${id}: expected exactly 4 primary exercises, got ${exercises.length}`);
  }
  if (repeatExercises.length !== 4) {
    throw new Error(`${id}: expected exactly 4 repeat exercises, got ${repeatExercises.length}`);
  }
  const finalSources = sources && sources.length ? sources : [ORIGINAL_SOURCE];
  if (!finalSources.some((s) => s.licenseStatus === 'original')) {
    throw new Error(`${id}: must include at least one original-license source`);
  }
  if (!notes) {
    throw new Error(`${id}: review notes are required`);
  }

  return {
    id,
    order,
    title: bi(titleEn, titleAr),
    objectives: objectives.map((o) => bi(o.en, o.ar)),
    prerequisites,
    estimatedMinutes,
    sections,
    exercises,
    repeatExercises,
    sources: finalSources,
    review: pendingReview(notes),
  };
}

