        'Most sentences show case with a visible vowel, but some names (those ending in alif maqsura, like موسى or ليلى) never show a visible case ending, even fully vocalized. When two such names appear together, word order alone often signals the doer, though context can still overturn that guess.',
        'تُظهر معظم الجمل الحالة الإعرابية بحركة ظاهرة، لكن بعض الأعلام (المنتهية بألف مقصورة، مثل موسى أو ليلى) لا تُظهر حركة إعراب أبدًا حتى مع التشكيل الكامل. وإذا اجتمع اسمان كهذين، فترتيب الكلمات وحده يدل غالبًا على الفاعل، وإن كان السياق قد يغيّر هذا الترجيح.',
